from datetime import datetime, timedelta
from typing import Dict, Optional


class Appointment:
    def __init__(
        self,
        appointment_id: int,
        patient: str,
        doctor: str,
        start: datetime,
        end: datetime,
    ) -> None:
        self.id = appointment_id
        self.patient = patient
        self.doctor = doctor
        self.start = start
        self.end = end
        self.cancelled = False
        self.slot_blocked = True


class Scheduler:
    def __init__(self) -> None:
        self._next_id: int = 1
        self._appointments: Dict[int, Appointment] = {}

    def book(
        self,
        patient: str,
        doctor: str,
        start: datetime,
        end: datetime,
        now: datetime,
    ) -> int:
        """Book an appointment; returns its id. `now` is the current time."""
        if start >= end:
            raise ValueError("Appointment start time must be before end time.")

        # Check if the patient already has an upcoming appointment.
        # An appointment is upcoming if it has not ended yet relative to `now`,
        # or if it starts after `now`. Standard definition: end > now or start >= now.
        # Active (non-cancelled) appointments with end > now are upcoming.
        for appt in self._appointments.values():
            if appt.patient == patient and not appt.cancelled:
                if appt.end > now:
                    raise ValueError(
                        f"Patient '{patient}' already has an upcoming appointment."
                    )

        # Check if doctor is free during the requested interval
        if not self.is_free(doctor, start, end):
            raise ValueError(
                f"Doctor '{doctor}' is not available between {start} and {end}."
            )

        appt_id = self._next_id
        self._next_id += 1
        self._appointments[appt_id] = Appointment(
            appt_id, patient, doctor, start, end
        )
        return appt_id

    def cancel(self, appointment_id: int, now: datetime) -> None:
        """Cancel an appointment given its id and the current time."""
        appt = self._appointments.get(appointment_id)
        if appt is None:
            raise KeyError(f"Appointment with id {appointment_id} does not exist.")

        if appt.cancelled:
            return

        appt.cancelled = True
        # If cancelled less than 24 hours before start, the slot remains blocked.
        # If cancelled 24 hours or more in advance, the slot is freed.
        if (appt.start - now) >= timedelta(hours=24):
            appt.slot_blocked = False
        else:
            appt.slot_blocked = True

    def is_free(self, doctor: str, start: datetime, end: datetime) -> bool:
        """True if the doctor can be booked between start and end."""
        if start >= end:
            raise ValueError("Start time must be before end time.")

        for appt in self._appointments.values():
            if appt.doctor == doctor and appt.slot_blocked:
                # Two intervals [start, end) and [appt.start, appt.end) overlap
                # if start < appt.end and end > appt.start.
                # Touching intervals (start == appt.end or end == appt.start) do not overlap.
                if max(start, appt.start) < min(end, appt.end):
                    return False

        return True
